public class Meal{

  private int price;

  public Meal(int p){
    price = p;
  }

  public int getPrice(){
    return price;
  }

  public void inc(){
    price++;
  }
}

public class Lunch <*1> Meal{

  private boolean hasDrink;

  public Lunch(int p, boolean d){
    super( p );
    hasDrink = d;
  }

  public int getPrice(){
    int result = super.getPrice() / 2;
    if( hasDrink )
      result++;
    return result;
  }
}

//////////////////////////////////////////
// client code
Meal sat = new Meal(5);
sat.inc();
System.out.print( sat.getPrice() ); //Line 1


Meal sun = new Lunch(13, true);
System.out.print( sun.getPrice() ); //Line 2

