37.1 
/* nextDouble() throws an 
   InputMisMatchException when the next   
   input token cannot be translated into  
   valid double value.  

   nextDouble() throws a 
   NoSuchElementException if the input is  
   exhausted. 
*/ 

public static void handle(Scanner s){ 
  double total = 0.0; 
  try{ 
    for(int i = 0; i < 10; i++) 
      total += s.nextDouble(); 
    System.out.print( total ); 
  } 
  catch(InputMismatchException e1){ 
    System.out.print("not"); 
  } 
  catch(NoSuchElementException e2){ 
    System.out.print("out"); 
  } 
  System.out.print( total ); 
}  
QUESTION  30 



